const defaults={favorites:catalog.slice(0,6).map(a=>a.id),scene:'mountain',glass:16,blur:24,shine:55,accent:'#66d9ff',darkness:52,motion:true,font:'normal'};
let prefs;try{prefs={...defaults,...JSON.parse(localStorage.getItem('konka-glass-v1')||'{}')}}catch{prefs={...defaults}};
prefs.favorites=Array.isArray(prefs.favorites)?[...new Set(prefs.favorites)].filter(id=>typeof id==='string'&&(typeof PeepTV!=='undefined'||catalog.some(a=>a.id===id))):defaults.favorites;
let page='home',lastFocus=null,toastTimer;
const panel=$('#panel');
let savedPrefs='';function save(){try{const value=JSON.stringify(prefs);if(value!==savedPrefs){localStorage.setItem('konka-glass-v1',value);savedPrefs=value}}catch{notify('O navegador não permitiu salvar suas preferências.')}}
function apply(){document.body.dataset.scene=prefs.scene;document.body.classList.toggle('reduced',!prefs.motion);document.documentElement.style.setProperty('--glass',Math.min(30,Math.max(3,Number(prefs.glass)||9))/100);document.documentElement.style.setProperty('--blur','18px');document.documentElement.style.fontSize=prefs.font==='large'?'19px':'16px';$('#selected-description').style.fontSize=prefs.font==='large'?'15px':'';$('.subtitle').style.fontSize=prefs.font==='large'?'18px':'';save()}
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function updateSelected(app){$('#selected-name').textContent=app.name;$('#selected-description').textContent=app.description}
function render(){const apps=page==='apps'?catalog:prefs.favorites.map(id=>catalog.find(a=>a.id===id)).filter(Boolean);$('#apps').replaceChildren();for(const app of apps){const b=document.createElement('button');b.className='app-card';if(app.nativeIcon)b.classList.add('has-native-icon');b.dataset.id=app.id;b.setAttribute('aria-label',`Abrir ${app.name}`);b.style.setProperty('--app-color',app.color);b.innerHTML=app.logo+'<span class="card-name"></span>';b.querySelector('.card-name').textContent=app.name;b.querySelector('img')?.addEventListener('error',e=>{e.target.hidden=true;b.classList.add('logo-unavailable')});b.addEventListener('focus',()=>updateSelected(app));b.addEventListener('pointerenter',()=>updateSelected(app));b.addEventListener('click',()=>openApp(app));$('#apps').append(b)}if(apps[0])updateSelected(apps[0]);else{$('#selected-name').textContent='Sua home, do seu jeito';$('#selected-description').textContent='Use Organizar para adicionar favoritos.'}}
function navigate(next){page=next;document.body.classList.toggle('ambient',next==='ambient');document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===next);b.setAttribute('aria-current',b.dataset.page===next?'page':'false')});$('#section-title').textContent=next==='apps'?'Sua biblioteca':'Seus favoritos';$('#heading').innerHTML=next==='apps'?'Todas as suas<br>possibilidades.':'Seu espaço.<br>Suas escolhas.';$('#subtitle').textContent=next==='apps'?(typeof PeepTV!=='undefined'?'Aplicativos disponíveis nesta TV.':'Aplicativos de exemplo para explorar a navegação.'):'O que você gosta. Do jeito que você prefere.';$('#edit').hidden=next==='apps';render()}
function show(html){window.dispatchEvent(new Event('peep-panel-replace'));lastFocus=document.activeElement;$('#panel-content').innerHTML=html;panel.showModal()}
function openApp(app){show(`<p class="eyebrow">PRÉVIA INTERATIVA</p><h2>${app.name}</h2><p>Este é o ponto de abertura do aplicativo. Na versão Android, ele abrirá o ${app.name} instalado na sua TV.</p><p>Esta prévia permite avaliar o visual e a navegação. Não está conectada à Konka e não instala aplicativos.</p><button class="panel-button" id="return-home">Voltar à tela inicial</button>`);$('#return-home').onclick=()=>panel.close()}
panel.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)panel.close()}});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();navigate('home')};$('#all-apps').onclick=()=>{navigate('apps');$('#apps button')?.focus()};
function appearance(){show(`<p class="eyebrow">DO SEU JEITO</p><h2>Personalizar</h2><p>Pequenos ajustes para uma tela que combina com você.</p><label class="option">Presença do vidro<input id="glass-range" type="range" min="3" max="30" value="${prefs.glass}" aria-label="Intensidade do vidro"></label><label class="option">Animações suaves<input id="motion-toggle" type="checkbox" ${prefs.motion?'checked':''}></label><label class="option">Tamanho do texto<select id="font-size"><option value="normal">Padrão</option><option value="large" ${prefs.font==='large'?'selected':''}>Ampliado</option></select></label><button id="change-scene" class="panel-button">Escolher ambiente</button><button id="reset" class="text-button">Restaurar aparência</button>`);$('#glass-range').oninput=e=>{prefs.glass=+e.target.value;apply()};$('#motion-toggle').onchange=e=>{prefs.motion=e.target.checked;apply()};$('#font-size').onchange=e=>{prefs.font=e.target.value;apply()};$('#change-scene').onclick=scenes;$('#reset').onclick=()=>{prefs={...defaults,favorites:[...prefs.favorites]};apply();appearanceContentReset()}}
function appearanceContentReset(){panel.close();appearance();notify('Aparência restaurada.')}
$('#settings').onclick=()=>settingsMenu();
function scenes(){if(panel.open)panel.close();show('<p class="eyebrow">RESPIRA. VOCÊ CHEGOU.</p><h2>Seu ambiente</h2><p>Três paisagens abstratas, a mesma tranquilidade.</p><div class="scene-picker"><button class="scene-choice" data-scene="mountain">Serra azul</button><button class="scene-choice" data-scene="dusk">Fim de tarde</button><button class="scene-choice" data-scene="forest">Horizonte verde</button></div>');document.querySelectorAll('.scene-choice').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.scene===prefs.scene));b.onclick=()=>{prefs.scene=b.dataset.scene;apply();document.querySelectorAll('.scene-choice').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));notify(`Ambiente: ${b.textContent}`)}})}
$('#wallpaper').onclick=scenes;
$('#inputs').onclick=()=>{show('<p class="eyebrow">ACESSO RÁPIDO</p><h2>Entradas da TV</h2><p>Na versão Android, este atalho será integrado ao seletor de entradas disponível na sua Konka.</p><p>As portas e os dispositivos conectados serão identificados na TV. A prévia não tem acesso a eles.</p><button class="panel-button" id="input-close">Entendido</button>');$('#input-close').onclick=()=>panel.close()};
$('#profile').onclick=()=>show('<p class="eyebrow">BEM-VINDO DE VOLTA</p><h2>Olá, Abel.</h2><p>Uma tela mais simples para os seus momentos em casa.</p><div class="option"><span>Favoritos escolhidos</span><strong>'+prefs.favorites.length+'</strong></div><div class="option"><span>Preferências</span><span>Salvas neste navegador</span></div>');
function organize(){show('<p class="eyebrow">MENOS PROCURA, MAIS ESCOLHA</p><h2>Seus favoritos</h2><p>Use + para adicionar, − para remover e as setas para mudar a ordem.</p><div id="edit-list"></div>');editList()}
function editList(focusId){const ids=[...prefs.favorites,...catalog.filter(a=>!prefs.favorites.includes(a.id)).map(a=>a.id)];$('#edit-list').replaceChildren();for(const id of ids){const app=catalog.find(a=>a.id===id),index=prefs.favorites.indexOf(id);const row=document.createElement('div');row.className='edit-row';const label=document.createElement('span');label.textContent=app.name;row.append(label);if(index>=0){for(const [delta,label] of [[-1,'Mover para a esquerda'],[1,'Mover para a direita']]){const b=document.createElement('button');b.textContent=delta<0?'←':'→';b.setAttribute('aria-label',`${label}: ${app.name}`);b.disabled=index+delta<0||index+delta>=prefs.favorites.length;b.onclick=()=>{[prefs.favorites[index],prefs.favorites[index+delta]]=[prefs.favorites[index+delta],prefs.favorites[index]];save();render();editList(id)};row.append(b)}}const toggle=document.createElement('button');toggle.textContent=index>=0?'−':'+';toggle.dataset.edit=id;toggle.setAttribute('aria-label',`${index>=0?'Remover':'Adicionar'} ${app.name} ${index>=0?'dos':'aos'} favoritos`);toggle.onclick=()=>{prefs.favorites=index>=0?prefs.favorites.filter(x=>x!==id):[...prefs.favorites,id];save();render();editList(id)};row.append(toggle);$('#edit-list').append(row)}if(focusId)document.querySelector(`[data-edit="${focusId}"]`)?.focus()}
$('#edit').onclick=organize;
$('#help').onclick=()=>show('<p class="eyebrow">KONKA GLASS · ESTUDO 01</p><h2>Feito para o sofá.</h2><p>Explore com as setas e Enter, ou use o mouse. Escape fecha os painéis e retorna ao início. A tecla H também retorna à home; F alterna a tela cheia.</p><p>Favoritos e aparência são salvos apenas neste navegador. Os aplicativos são exemplos; marcas e nomes pertencem aos respectivos titulares.</p><p>Esta é uma prévia visual para avaliação. O desempenho e a integração com o Android TV ainda precisam ser testados na Konka.</p>');
function clock(){const now=new Date();$('#clock').textContent=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(now);$('#date').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(now);$('#clock').dateTime=now.toISOString()};clock();setInterval(clock,15000);
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key==='Escape'&&!panel.open){navigate('home');$('.app-card')?.focus();return}if(e.key.toLowerCase()==='h'&&!panel.open){navigate('home');$('.app-card')?.focus();return}if(e.key.toLowerCase()==='f'&&!panel.open){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>notify('Tela cheia indisponível neste navegador.'));else document.exitFullscreen?.();return}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const root=panel.open?panel:document;const targets=[...root.querySelectorAll('button:not(:disabled),a[href],input,select')].filter(el=>el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');const current=document.activeElement;if(!targets.includes(current)){e.preventDefault();(panel.open?targets[0]:$('.app-card')||targets[0])?.focus();return}const r=current.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2;const vertical=e.key==='ArrowDown'||e.key==='ArrowUp',sign=e.key==='ArrowDown'||e.key==='ArrowRight'?1:-1;let winner=null,best=Infinity;for(const el of targets){if(el===current)continue;const q=el.getBoundingClientRect(),dx=q.x+q.width/2-cx,dy=q.y+q.height/2-cy,primary=(vertical?dy:dx)*sign,cross=Math.abs(vertical?dx:dy);if(primary<=5)continue;const score=primary+cross*3;if(score<best){best=score;winner=el}}e.preventDefault();winner?.focus()});
apply();render();
